WITH enriched AS (SELECT *, SUM(monthly_fee) OVER (PARTITION BY plan, status ORDER BY end_date, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_monthly_fee, ROW_NUMBER() OVER (ORDER BY monthly_fee, id) AS row_seq, SUM(monthly_fee) OVER (PARTITION BY status ORDER BY end_date, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_monthly_fee_2, RANK() OVER (PARTITION BY plan ORDER BY monthly_fee NULLS LAST) AS monthly_fee_rank, LAG(monthly_fee, 1, 0) OVER (PARTITION BY plan ORDER BY end_date, id) AS prev_monthly_fee FROM subscriptions) SELECT DATE_TRUNC('WEEK', start_date) AS week_start, DATE_TRUNC('QUARTER', start_date) AS quarter_start, SUM(row_seq) AS total_row_seq, COUNT(*) AS cnt, SUM(CASE WHEN status = 'EXPIRED' THEN cumulative_monthly_fee ELSE 0 END) AS expired_cumulative_monthly_fee, GROUPING_ID() AS grouping_id FROM enriched GROUP BY CUBE (DATE_TRUNC('WEEK', start_date), DATE_TRUNC('QUARTER', start_date)) ORDER BY cnt
